{"title": "Volume écrit par couche (enregistrements)", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "autosize": {
    "type": "fit"
  },
  "width": "container",
  "height": "container",
  "data": {
    "url": {
      "index": "scipulse-pipeline-metrics",
      "body": {
        "size": 0,
        "aggs": {
          "layer": {
            "terms": {
              "field": "layer.keyword"
            },
            "aggs": {
              "t": {
                "date_histogram": {
                  "field": "@timestamp",
                  "fixed_interval": "1h"
                },
                "aggs": {
                  "n": {
                    "sum": {
                      "field": "records_out"
                    }
                  }
                }
              }
            }
          }
        }
      },
      "%context%": true,
      "%timefield%": "@timestamp"
    },
    "format": {
      "property": "aggregations.layer.buckets"
    }
  },
  "transform": [
    {
      "flatten": [
        "t.buckets"
      ],
      "as": [
        "b"
      ]
    },
    {
      "calculate": "datum.b.key",
      "as": "heure"
    },
    {
      "calculate": "datum.b.n.value",
      "as": "enregistrements"
    }
  ],
  "mark": {
    "type": "bar",
    "tooltip": true
  },
  "encoding": {
    "x": {
      "field": "heure",
      "type": "temporal",
      "title": null
    },
    "y": {
      "field": "enregistrements",
      "type": "quantitative",
      "title": null
    },
    "color": {
      "field": "key",
      "type": "nominal",
      "title": "Couche",
      "scale": {
        "domain": [
          "bronze",
          "silver",
          "gold"
        ],
        "range": [
          "#b08d57",
          "#9aa5b1",
          "#d4af37"
        ]
      }
    }
  }
}"}}

