{"title": "Évolution annuelle des publications (6 catégories principales)", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "autosize": {
    "type": "fit"
  },
  "width": "container",
  "height": "container",
  "data": {
    "url": {
      "index": "arxiv-papers",
      "body": {
        "size": 0,
        "aggs": {
          "cat": {
            "terms": {
              "field": "primary_category",
              "size": 6
            },
            "aggs": {
              "year": {
                "histogram": {
                  "field": "published_year",
                  "interval": 1,
                  "min_doc_count": 0
                }
              }
            }
          }
        }
      },
      "%context%": true,
      "%timefield%": "published_at"
    },
    "format": {
      "property": "aggregations.cat.buckets"
    }
  },
  "transform": [
    {
      "flatten": [
        "year.buckets"
      ],
      "as": [
        "y"
      ]
    },
    {
      "calculate": "datum.y.key",
      "as": "annee"
    },
    {
      "calculate": "datum.y.doc_count",
      "as": "articles"
    }
  ],
  "mark": {
    "type": "line",
    "point": true,
    "tooltip": true
  },
  "encoding": {
    "x": {
      "field": "annee",
      "type": "ordinal",
      "title": "Ann\u00e9e de soumission"
    },
    "y": {
      "field": "articles",
      "type": "quantitative",
      "title": "Articles"
    },
    "color": {
      "field": "key",
      "type": "nominal",
      "title": "Cat\u00e9gorie"
    }
  }
}"}}

{"title": "Citations vs signal Hacker News (articles sur HN)", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "autosize": {
    "type": "fit"
  },
  "width": "container",
  "height": "container",
  "data": {
    "url": {
      "index": "arxiv-papers-enriched",
      "body": {
        "size": 3000,
        "_source": [
          "title",
          "cited_by_count",
          "hn_points",
          "impact_segment",
          "impact_score"
        ],
        "query": {
          "term": {
            "on_hn": true
          }
        }
      }
    },
    "format": {
      "property": "hits.hits"
    }
  },
  "transform": [
    {
      "calculate": "log(1 + (datum._source.cited_by_count || 0)) / LN10",
      "as": "cit"
    },
    {
      "calculate": "log(1 + datum._source.hn_points) / LN10",
      "as": "hn"
    },
    {
      "calculate": "datum._source.impact_segment",
      "as": "segment"
    },
    {
      "calculate": "datum._source.title",
      "as": "titre"
    }
  ],
  "mark": {
    "type": "point",
    "filled": true,
    "opacity": 0.6
  },
  "encoding": {
    "x": {
      "field": "hn",
      "type": "quantitative",
      "title": "log10(1 + points HN)"
    },
    "y": {
      "field": "cit",
      "type": "quantitative",
      "title": "log10(1 + citations)"
    },
    "color": {
      "field": "segment",
      "type": "nominal",
      "title": "Segment"
    },
    "tooltip": [
      {
        "field": "titre"
      },
      {
        "field": "_source.cited_by_count",
        "title": "citations"
      },
      {
        "field": "_source.hn_points",
        "title": "points HN"
      }
    ]
  }
}"}}

{"title": "Sous-domaines en croissance (depuis 2020) : croissance annuelle vs impact moyen", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "autosize": {
    "type": "fit"
  },
  "width": "container",
  "height": "container",
  "data": {
    "url": {
      "index": "arxiv-papers-enriched",
      "body": {
        "size": 0,
        "aggs": {
          "cat": {
            "terms": {
              "field": "primary_category",
              "size": 25,
              "min_doc_count": 100
            },
            "aggs": {
              "g": {
                "avg": {
                  "field": "category_yoy_growth_pct"
                }
              },
              "s": {
                "avg": {
                  "field": "impact_score"
                }
              },
              "h": {
                "sum": {
                  "field": "hn_stories"
                }
              }
            }
          }
        },
        "query": {
          "range": {
            "published_year": {
              "gte": 2020
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.cat.buckets"
    }
  },
  "transform": [
    {
      "calculate": "datum.g.value",
      "as": "croissance"
    },
    {
      "calculate": "datum.s.value",
      "as": "impact"
    },
    {
      "calculate": "datum.h.value",
      "as": "stories_hn"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "circle",
        "opacity": 0.7,
        "tooltip": true
      },
      "encoding": {
        "size": {
          "field": "doc_count",
          "type": "quantitative",
          "title": "Articles"
        },
        "color": {
          "field": "stories_hn",
          "type": "quantitative",
          "title": "Stories HN"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "dy": -12
      },
      "encoding": {
        "text": {
          "field": "key"
        }
      }
    }
  ],
  "encoding": {
    "x": {
      "field": "croissance",
      "type": "quantitative",
      "title": "Croissance annuelle moyenne (%)"
    },
    "y": {
      "field": "impact",
      "type": "quantitative",
      "title": "Score d'impact moyen"
    }
  }
}"}}

